// 苍绿之眼 pieces for ascii.rest (MIT, https://github.com/bas3line/ascii).
//
// A piece is a tiny module: `meta` (size, frame rate, palette) and a frame
// function `(t) => string`, where t is in seconds. That is the whole contract,
// so these play in every place a library piece does: the <ascii-art> tag (with
// `src`), `Ascii` in React, `mount()` from "ascii.rest", or a terminal.
//
//   node tools/ascii/build.mjs                 # -> static/ascii-cloak/*.js, *.svg
//   node tools/ascii/build.mjs --preview rain  # print frames to the terminal
//
// The palette is the game's own: the dark instrument panel (#050806), the eye's
// green (#9ff0c0), and the dark red rain of 死象 (D-XXXX).
// ---------- shared helpers ----------
/** A small integer hash, so a glyph is a function of where and when it is. */
function hash(a, b = 0, c = 0) {
    let h = Math.imul(a ^ 0x9e3779b9, 0x85ebca6b) ^ Math.imul(b + 1, 0xc2b2ae35) ^ Math.imul(c + 1, 0x27d4eb2d);
    h = Math.imul(h ^ (h >>> 15), 0x2c1b3c6d);
    h = Math.imul(h ^ (h >>> 12), 0x297a2d39);
    return ((h ^ (h >>> 15)) >>> 0) / 4294967296;
}
/** Smooth 0..1 noise along x, periodic over `period`, seeded by row. */
function swell(x, period, row) {
    const u = x / period;
    const i = Math.floor(u);
    const f = u - i;
    const s = f * f * (3 - 2 * f);
    return hash(i, row, 7) * (1 - s) + hash(i + 1, row, 7) * s;
}
class Grid {
    constructor(cols, rows) {
        this.cols = cols;
        this.rows = rows;
        this.chars = new Array(cols * rows).fill(" ");
        this.ink = new Array(cols * rows).fill(-1);
    }
    set(c, r, ch, ink) {
        c = Math.round(c);
        r = Math.round(r);
        if (c < 0 || c >= this.cols || r < 0 || r >= this.rows)
            return;
        const i = r * this.cols + c;
        this.chars[i] = ch;
        this.ink[i] = ink;
    }
    get(c, r) {
        if (c < 0 || c >= this.cols || r < 0 || r >= this.rows)
            return " ";
        return this.chars[r * this.cols + c];
    }
    text() {
        const out = [];
        for (let r = 0; r < this.rows; r++)
            out.push(this.chars.slice(r * this.cols, (r + 1) * this.cols).join(""));
        // Trailing blank lines carry nothing; trimming keeps every piece tight.
        while (out.length && !out[out.length - 1].trim())
            out.pop();
        return out.join("\n");
    }
    /** The frame: the text, and for a coloured piece the ink of every cell, space or not. */
    frame(env) {
        if (env?.color)
            for (let i = 0; i < env.color.length; i++)
                env.color[i] = this.ink[i] < 0 ? BG : this.ink[i];
        return this.text();
    }
}
/**
 * The palette every 苍绿之眼 piece draws from, dark-panel first: the panel, the
 * eye's green and its glow, a far teal, a body teal, the near paper white, the
 * blood red of the rain, and the two lights of a sclera.
 */
const PALETTE = ["#050806", "#9ff0c0", "#c8f7da", "#3f7a5a", "#6fbf93", "#d3e6da", "#8c2f24", "#2a3d33", "#16312a"];
// Palette indices
const BG = 0;
const INK = 1;
const GLOW = 2;
const FAR = 3;
const BODY = 4;
const NEAR = 5;
const RED = 6;
const SCLERA = 7; // the eye's white: light, so the dark pupil reads in it
const SCLERA_DIM = 8; // its shaded rim
const PUPIL = 0; // the panel itself
// ---------- chapter plates (tools/ascii/plates.ts) ----------
// Chapter plates: one thin strip (64 × 9) under each chapter's title.
//
// A frontispiece, not a scene. PRODUCT.md asks for restrained motion on reading
// pages, so a plate is one band tall, drawn in the game's own inks, and holds
// still for a reader who prefers reduced motion. Every plate is the same size,
// so the chapters read as one set; only the motif changes.
//
// This file is concatenated after cloak.ts's helpers by tools/ascii/build.mjs,
// so it uses Grid, hash, swell and the palette indices without importing them.
const PLATE_COLS = 64;
const PLATE_ROWS = 7;
const PLATE_MID = 3;
/** A 64 × 9 strip, drawn by whichever motif the chapter is about. */
function plate(motif, name, note) {
    const cols = PLATE_COLS;
    const rows = PLATE_ROWS;
    return {
        meta: {
            name,
            category: "scenes",
            note,
            cols,
            rows,
            fps: 12,
            palette: PALETTE,
            ground: PALETTE[0],
            loop: 9,
            still: 2.4,
        },
        default: () => (t, env) => {
            const g = new Grid(cols, rows);
            switch (motif) {
                // 0x01 呼吸：一条随呼吸起伏的光带。
                case "breath": {
                    for (let c = 0; c < cols; c++) {
                        const breathe = 0.5 + 0.5 * Math.sin(t * 1.1 - c * 0.18);
                        const half = 0.5 + breathe * 3.1;
                        for (let r = 0; r < rows; r++) {
                            const d = Math.abs(r - PLATE_MID);
                            if (d > half)
                                continue;
                            const edge = half - d;
                            g.set(c, r, edge > 1.6 ? "▓" : edge > 0.7 ? "▒" : "░", edge > 1.6 ? GLOW : edge > 0.7 ? INK : FAR);
                        }
                    }
                    break;
                }
                // 0x02 听见：四十二个模块同时说话。
                case "modules": {
                    const N = 42;
                    for (let i = 0; i < N; i++) {
                        const c = (i % 21) * 3;
                        const r = i < 21 ? PLATE_MID - 2 : PLATE_MID + 2;
                        const beat = Math.floor(t * 1.6) + i;
                        const on = hash(i, beat, 5) > 0.42;
                        g.set(c, r, on ? "█" : "░", on ? INK : FAR);
                        g.set(c + 1, r, on ? "█" : "░", on ? INK : FAR);
                    }
                    break;
                }
                // 0x03 看见：一层压一层的丛林。
                case "canopy": {
                    for (let r = 0; r < rows; r++) {
                        const depth = r / (rows - 1);
                        for (let c = 0; c < cols; c++) {
                            const sway = swell(c * 0.7 + t * (0.6 + depth * 1.4), 16, r);
                            if (sway < 0.28 + depth * 0.32)
                                continue;
                            const ch = depth > 0.62 ? "▓" : depth > 0.32 ? "▒" : "░";
                            const ink = depth > 0.62 ? GLOW : depth > 0.32 ? INK : FAR;
                            g.set(c, r, ch, ink);
                        }
                    }
                    break;
                }
                // 0x04 酒馆 / 0x07 死象：同一场雨，两种颜色。
                case "drizzle":
                case "redrain": {
                    const red = motif === "redrain";
                    const far = red ? RED : FAR;
                    const near = red ? NEAR : INK;
                    if (red) {
                        for (let c = 0; c < cols; c++)
                            if (hash(c, 3, 9) > 0.35)
                                g.set(c, rows - 1, "▁", FAR);
                    }
                    const layers = red
                        ? [
                            { n: 34, v: 8, len: 2, ink: far },
                            { n: 18, v: 15, len: 3, ink: near },
                        ]
                        : [
                            { n: 26, v: 7, len: 2, ink: far },
                            { n: 12, v: 13, len: 3, ink: near },
                        ];
                    for (const layer of layers) {
                        for (let i = 0; i < layer.n; i++) {
                            const col = hash(i, 1, layer.n) * (cols + 4) - 2;
                            const span = rows + layer.len;
                            const y = ((t * layer.v + hash(i, 2, layer.n) * span) % span) - layer.len;
                            for (let k = 0; k < layer.len; k++) {
                                const r = Math.floor(y) + k;
                                if (r < 0 || r >= rows)
                                    continue;
                                g.set(col + (r - Math.floor(y)) * 0.5, r, "╱", layer.ink);
                            }
                        }
                    }
                    break;
                }
                // 0xA0 选择：三条路从同一个点分开。
                case "paths": {
                    const start = 2;
                    const ends = [0, PLATE_MID, rows - 1];
                    ends.forEach((end, k) => {
                        for (let c = start; c < cols - 1; c++) {
                            const u = (c - start) / (cols - 1 - start);
                            const r = PLATE_MID + (end - PLATE_MID) * u;
                            if ((c + k) % 3 === 0)
                                g.set(c, r, "·", k === 1 ? INK : FAR);
                        }
                    });
                    g.set(0, PLATE_MID, "◉", GLOW);
                    g.set(cols - 1, ends[Math.floor(t / 3) % 3], "◆", GLOW);
                    break;
                }
                // 0xA1 醒来：一条航线，和航线上的一个点。
                case "route": {
                    const at = (c) => PLATE_MID - 1 + Math.sin(c * 0.13) * 1.6;
                    for (let c = 0; c < cols; c++)
                        if (c % 2 === 0)
                            g.set(c, at(c), "·", FAR);
                    const p = (t * 9) % (cols - 2);
                    g.set(p, at(p), "◆", GLOW);
                    for (let k = 1; k <= 3; k++) {
                        const q = p - k * 3;
                        if (q > 0)
                            g.set(q, at(q), "·", INK);
                    }
                    break;
                }
                // 0xA1_2 月圆：月亮走完一轮。
                case "moon": {
                    const cx = cols - 12;
                    const phase = (t % 9) / 9;
                    const R = 3;
                    for (let r = -R; r <= R; r++) {
                        for (let c = -R * 2; c <= R * 2; c++) {
                            const d = Math.hypot(c / 2, r);
                            if (d > R)
                                continue;
                            const shadow = (phase - 0.5) * 8;
                            const lit = c / 2 > shadow;
                            g.set(cx + c / 2, PLATE_MID + r, lit ? "▓" : "░", lit ? GLOW : FAR);
                        }
                    }
                    for (let c = 0; c < cx - 6; c++) {
                        if (hash(c, Math.floor(t * 0.4), 7) > 0.86)
                            g.set(c, 1 + Math.round(hash(c, 2, 7) * 2), "·", FAR);
                    }
                    break;
                }
                // 0xA1_3 译码 / 0xA4 密室：频谱，以及被擦掉的那一段。
                case "signal": {
                    for (let c = 0; c < cols; c++) {
                        const h = 1 + Math.round(swell(c * 1.1 + t * 7, 13, Math.floor(t * 3)) * 6);
                        for (let r = rows - 1; r > rows - 1 - h; r--) {
                            g.set(c, r, r === rows - h + 1 ? "▓" : "▒", r > rows - 3 ? GLOW : INK);
                        }
                    }
                    // A narrow band where the bars are missing: the words taken out of the rain.
                    const gap = Math.floor((t * 6) % cols);
                    for (let r = 0; r < rows; r++) {
                        for (let c = gap; c < gap + 3; c++)
                            g.set(c, r, " ", BG);
                    }
                    break;
                }
                // 0xA1_4 漂浮：水面上一个透明的球。
                case "float": {
                    // Water on one line, and a transparent ball resting on it: the outline
                    // is drawn as a ring, not a disc, or it reads as a box.
                    const water = PLATE_MID + 3;
                    for (let c = 0; c < cols; c++) {
                        const w = water + (Math.sin(c * 0.25 + t * 1.6) > 0.6 ? -1 : 0);
                        g.set(c, w, "~", FAR);
                    }
                    const cx = cols / 2;
                    const cy = water - 3 + Math.sin(t * 0.8) * 0.5;
                    const R = 2.7;
                    for (let r = -4; r <= 4; r++) {
                        for (let c = -6; c <= 6; c++) {
                            const d = Math.hypot(c / 2, r);
                            if (Math.abs(d - R) > 0.55)
                                continue;
                            g.set(cx + c / 2, cy + r, "░", INK);
                        }
                    }
                    g.set(cx - 1, cy - 1, "°", GLOW);
                    break;
                }
                // 0xA1_5 世界线：一条几乎不动的线，偶尔偏一下。
                case "horizon": {
                    // The line itself is always there; a deviation is a short spike above
                    // it, never a gap in it (a gap reads as a rendering fault).
                    const beat = Math.floor(t * 2);
                    for (let c = 0; c < cols; c++) {
                        g.set(c, PLATE_MID, "─", FAR);
                        if (hash(c, beat, 11) > 0.93) {
                            g.set(c, PLATE_MID - 1, "╱", RED);
                            g.set(c, PLATE_MID - 2, "·", RED);
                        }
                    }
                    const p = Math.floor((t * 6) % cols);
                    g.set(p, PLATE_MID, "◆", GLOW);
                    break;
                }
                // 0xA2 冰可乐 / 0xA3 爆炸：气泡往上跑。
                case "bubbles": {
                    // A few fixed columns, each with two or three bubbles rising at its own
                    // speed: a scatter of dots reads as noise, a column reads as a glass.
                    for (let c = 2; c < cols; c += 4) {
                        const n = 2 + Math.floor(hash(c, 9, 6) * 2);
                        for (let i = 0; i < n; i++) {
                            const speed = 2.5 + hash(c, i, 6) * 3.5;
                            const span = rows + 4;
                            const y = span - ((t * speed + hash(c, i, 7) * span) % span);
                            g.set(c + (i % 2), y, hash(c, i, 8) > 0.6 ? "○" : "°", hash(c, i, 9) > 0.5 ? NEAR : INK);
                        }
                    }
                    break;
                }
                // 0xA9 小黑盒：三个盒子，一道扫描线。
                case "boxes": {
                    const at = [6, 26, 46];
                    for (const x of at) {
                        for (let c = 0; c < 9; c++) {
                            g.set(x + c, PLATE_MID - 2, "─", FAR);
                            g.set(x + c, PLATE_MID + 2, "─", FAR);
                        }
                        for (let r = -2; r <= 2; r++) {
                            g.set(x, PLATE_MID + r, "│", FAR);
                            g.set(x + 8, PLATE_MID + r, "│", FAR);
                        }
                    }
                    const sweep = Math.floor((t * 20) % (cols + 10)) - 5;
                    for (let r = 0; r < rows; r++) {
                        if (sweep >= 0 && sweep < cols)
                            g.set(sweep, r, "│", GLOW);
                    }
                    for (const x of at) {
                        if (sweep >= x && sweep <= x + 8)
                            g.set(x + 4, PLATE_MID, "◆", GLOW);
                    }
                    break;
                }
                // 0xA5 解答：一张一次只能看见一种颜色的照片。
                case "hue": {
                    for (let r = 0; r < rows; r++) {
                        for (let c = 0; c < cols; c++) {
                            if (hash(c, r, 12) < 0.45)
                                continue;
                            const band = (Math.floor((t * 2) % 5) + Math.floor(c / 8)) % 5;
                            g.set(c, r, "·", [FAR, INK, GLOW, NEAR, BODY][band]);
                        }
                    }
                    break;
                }
                // 0xB0 终局：睁开的眼睛。
                case "eyes": {
                    const cx = cols / 2;
                    const lift = 2.4;
                    for (let c = 0; c < cols; c++) {
                        const u = (c - cx) / 16;
                        if (Math.abs(u) > 1)
                            continue;
                        const h = Math.sqrt(1 - u * u) * lift;
                        g.set(c, PLATE_MID - h, "─", INK);
                        g.set(c, PLATE_MID + h, "─", INK);
                        for (let r = -h + 0.5; r <= h - 0.5; r += 0.5)
                            g.set(c, PLATE_MID + r, "░", SCLERA_DIM);
                    }
                    for (let r = -2; r <= 2; r++) {
                        for (let c = -4; c <= 4; c++) {
                            const d = Math.hypot(c / 2, r);
                            if (d > 1.9)
                                continue;
                            g.set(cx + c / 2, PLATE_MID + r, d < 0.7 ? "█" : "▓", d < 0.7 ? PUPIL : GLOW);
                        }
                    }
                    g.set(cx - 1, PLATE_MID - 1, "°", GLOW);
                    break;
                }
            }
            return g.frame(env);
        },
    };
}

function cloakPlateRoute() { return plate("route", "航线", "一条航线，和航线上的一个点"); }

export const meta = {
  "name": "航线",
  "category": "scenes",
  "note": "一条航线，和航线上的一个点",
  "cols": 64,
  "rows": 7,
  "fps": 12,
  "palette": [
    "#050806",
    "#9ff0c0",
    "#c8f7da",
    "#3f7a5a",
    "#6fbf93",
    "#d3e6da",
    "#8c2f24",
    "#2a3d33",
    "#16312a"
  ],
  "ground": "#050806",
  "loop": 9,
  "still": 2.4
};

export default cloakPlateRoute();
